/* Finite-field Diffie-Hellman, RFC 7919, against Python.
 *
 * Every expected value below was computed with Python's pow() by
 * files/gen_ffdhe_test.py, which recomputes each prime from the formula in
 * section 3 of the RFC and knows nothing about the implementation.  The two
 * secrets of each group are deterministic pseudorandom byte strings, so the
 * vectors are reproducible but are not the trivial small exponents.
 *
 * Each group is checked four ways: both public keys, the shared secret from
 * either side (which must agree), and the rejection of the two boundary
 * peer keys 1 and p - 1.
 */
