static int group_2048(void) {
  int r = 0;
  uint8_t pk[256], ss[256], bad[256];
  Hacl_FFDHE_ffdhe2048_secret_to_public(pk, sk_a_2048);
  r |= check("FFDHE-2048 public key A", pk, pk_a_2048, 256);
  Hacl_FFDHE_ffdhe2048_secret_to_public(pk, sk_b_2048);
  r |= check("FFDHE-2048 public key B", pk, pk_b_2048, 256);
  if (!Hacl_FFDHE_ffdhe2048_shared_secret(ss, sk_a_2048, pk_b_2048)) {
    printf("  FAIL FFDHE-2048 shared secret A rejected a good key\n");
    r = 1;
  }
  r |= check("FFDHE-2048 shared secret A", ss, ss_2048, 256);
  if (!Hacl_FFDHE_ffdhe2048_shared_secret(ss, sk_b_2048, pk_a_2048)) {
    printf("  FAIL FFDHE-2048 shared secret B rejected a good key\n");
    r = 1;
  }
  r |= check("FFDHE-2048 shared secret B", ss, ss_2048, 256);

  /* One is too small, p - 1 is too large, and both must be rejected with a
     zeroed output. */
  memset(bad, 0, 256);
  bad[256 - 1] = 1;
  memset(ss, 0xffU, 256);
  if (Hacl_FFDHE_ffdhe2048_shared_secret(ss, sk_a_2048, bad)) {
    printf("  FAIL FFDHE-2048 accepted the peer key one\n");
    r = 1;
  }
  memset(bad, 0, 256);
  r |= check("FFDHE-2048 rejection zeroes the output", ss, bad, 256);
  memset(ss, 0xffU, 256);
  if (Hacl_FFDHE_ffdhe2048_shared_secret(ss, sk_a_2048, pmax_2048)) {
    printf("  FAIL FFDHE-2048 accepted the peer key p - 1\n");
    r = 1;
  }
  r |= check("FFDHE-2048 rejection zeroes the output (p - 1)", ss, bad, 256);
  return r;
}

